function startBattle(keys){keys=Array.isArray(keys)?keys:[keys];let counts={},seen={},factor=keys.length===1?1:keys.length===2?.82:.66;keys.forEach(key=>counts[key]=(counts[key]||0)+1);state.enemies=keys.map(key=>{let base=enemies[key],index=seen[key]||0;seen[key]=index+1;let maxHp=Math.max(1,Math.round(base.maxHp*factor)),attackFactor=keys.length===1?1:keys.length===2?.82:.7;return{...base,name:counts[key]>1?base.name+' '+String.fromCharCode(65+index):base.name,maxHp,hp:maxHp,atk:Math.max(1,Math.round(base.atk*attackFactor)),exp:Math.max(1,Math.round(base.exp*factor)),key,turn:0,charging:false,defeated:false}});state.enemy=state.enemies[0];let e=state.enemy;for(let member of[state.hero,state.companion]){member.guarding=false;member.charged=false;member.expBoost=1}state.actor=state.hero.hp>0?'hero':'mage';state.mode='battle';resetBattleMotion();state.skillFx=null;state.battleReadyAt=performance.now()+700;state.busy=false;state.skillMenu=false;state.itemMenu=false;state.skillUses=Object.fromEntries(SKILLS.map(s=>[s.id,s.uses]));state.mageUses={heal:2};setMsg(e.boss?e.name+'が行く手を遮った！':state.enemies.length>1?state.enemies.length+'体の魔物が現れた！':e.name+'が現れた！');gameAudio?.startBattle();if(e.boss)sfx('enemy');sync();draw()}
function damage(atk,def){return Math.max(1,atk-Math.floor(def/2)+rand(-2,2))}
function openSkillMenu(){if(state.mode!=='battle'||state.busy)return;let member=currentActor(),learned=SKILLS.filter(s=>s.owner===state.actor&&member.learnedSkills.includes(s.id));if(!learned.length){setMsg(actorName(member)+'はまだワザを閃いていない。');return}sfx('menuOpen');$('#skillMenu').innerHTML=learned.map(s=>'<button data-skill="'+s.id+'" '+((state.skillUses[s.id]||0)<=0?'disabled':'')+'>✦ '+s.name+' <small>'+s.desc+'　残'+(state.skillUses[s.id]||0)+'回</small></button>').join('')+'<button class="back" data-skill="back">もどる</button>';state.itemMenu=false;state.skillMenu=true;sync()}
function closeSubMenu(){sfx('menuClose');state.skillMenu=false;state.itemMenu=false;sync()}
function openItemMenu(){if(state.mode!=='battle'||state.busy)return;sfx('menuOpen');let usable=Object.entries(ITEMS).filter(([id,item])=>item.usable&&itemCount(id)>0);$('#skillMenu').innerHTML=(usable.length?usable.map(([id,item])=>'<button data-item="'+id+'">'+item.icon+' '+item.name+' <small>'+item.desc+'　×'+itemCount(id)+'</small></button>').join(''):'<button disabled>使えるどうぐがない</button>')+'<button class="back" data-item="back">もどる</button>';state.skillMenu=false;state.itemMenu=true;sync()}
function mostInjuredMember(){let living=[state.hero,...(state.companion.active?[state.companion]:[])].filter(v=>v.hp>0&&v.hp<v.maxHp);return living.sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0]||null}
async function maybeSpark(member,action){let candidates=SKILLS.filter(s=>s.owner===state.actor&&member.lv>=s.lv&&!member.learnedSkills.includes(s.id));if(!candidates.length){member.chargeUsed=false;return false}let chance=sparkChanceForAction(action,!!member.chargeUsed),preferred=candidates.filter(s=>s.spark?.includes(action));member.chargeUsed=false;if(Math.random()>=chance)return false;let pool=preferred.length?preferred:candidates,skill=pool[Math.floor(Math.random()*pool.length)];member.learnedSkills.push(skill.id);sfx('level');speak('閃いた！ '+skill.name);setMsg('💡 '+actorName(member)+'は「'+skill.name+'」を閃いた！');sync();await sparkAnimation(skill.name,member);return true}
async function finishActorTurn(action){let member=currentActor();await maybeSpark(member,action);if(!livingEnemies().length){await win();return true}chooseEnemyTarget();if(state.actor==='hero'&&state.companion.active&&state.companion.hp>0){state.actor='mage';state.busy=false;setMsg('ミナの行動を選んでください。');sync();draw();return true}await enemyTurn();if(state.mode!=='battle')return true;state.hero.guarding=false;state.companion.guarding=false;state.actor=state.hero.hp>0?'hero':'mage';state.busy=false;setMsg(actorName()+'の行動を選んでください。');sync();draw();return true}
async function useBattleItem(id){if(state.mode!=='battle'||state.busy)return;if(id==='back'){closeSubMenu();return}let item=ITEMS[id];if(!item?.usable||itemCount(id)<=0)return;let targets=item.healAll?[state.hero,...(state.companion.active?[state.companion]:[])].filter(v=>v.hp>0&&v.hp<v.maxHp):[mostInjuredMember()].filter(Boolean);if(!targets.length){setMsg('回復が必要な仲間はいない。');return}state.busy=true;state.itemMenu=false;consumeItem(id);sfx('potion');let total=0;targets.forEach(target=>{let heal=Math.min(item.healAll||item.heal,target.maxHp-target.hp);target.hp+=heal;total+=heal;floatText('+'+heal,target===state.hero?53:112,175,'#6eff90')});setMsg(actorName()+'は '+item.name+'を使った！ HPが合計 '+total+' 回復！');sync();await delay(650);await finishActorTurn('item')}
function enemyAnchorX(foe){let visible=(state.enemies?.length?state.enemies:[state.enemy]).filter(v=>v&&!v.defeated);if(foe===state.enemy)return 230;let others=visible.filter(v=>v!==state.enemy),i=others.indexOf(foe);return i<=0?283:186}
function healTargets(){return[state.hero,...(state.companion.active?[state.companion]:[])].filter(v=>v.hp>0&&v.hp<v.maxHp)}
function skillMotion(s){if(state.actor==='hero'){if(s.motion==='starfire')return starfireAnimation(s.name);if(s.motion==='crescent')return comboSlashAnimation(s.name,Math.max(2,s.hits||2));if(s.motion==='whirl')return whirlAnimation(s.name);if(s.motion==='pierce')return pierceAnimation(s.name);if(s.motion==='heal')return healingAnimation(s.name);return heroAttackAnimation()}if(s.motion==='moonheal')return moonMagicAnimation('heal',s.name);if(s.motion==='moonveil')return moonMagicAnimation('veil',s.name);if(s.motion==='starshower')return starShowerAnimation(s.name,false);if(s.motion==='starfall')return starShowerAnimation(s.name,true);return moonMagicAnimation('attack',s.name)}
async function useSkill(id){if(state.mode!=='battle'||state.busy)return;if(id==='back'){closeSubMenu();return}let member=currentActor(),s=SKILLS.find(v=>v.id===id&&v.owner===state.actor);if(!s||member.hp<=0||!member.learnedSkills.includes(id))return;if((state.skillUses[id]||0)<=0){setMsg(s.name+'はこの戦闘ではもう使えない。');closeSubMenu();return}let group=s.healAll?healTargets():null,target=s.heal?mostInjuredMember():null;if((s.heal&&!target)||(s.healAll&&!group.length)){setMsg('HPは全員満タンだ。');state.skillMenu=false;sync();return}state.busy=true;state.skillMenu=false;state.skillUses[id]--;setMsg(actorName(member)+'の「'+s.name+'」！');speak(s.name+'！');let charged=!!member.charged;member.charged=false;member.chargeUsed=charged;if(s.heal||s.healAll){await skillMotion(s);let list=s.healAll?group:[target],amount=s.healAll||s.heal,total=0;list.forEach(t=>{let heal=Math.min(amount,t.maxHp-t.hp);t.hp+=heal;total+=heal;floatText('+'+heal,t===state.hero?53:112,175,'#9ffff0')});sfx('heal');setMsg(s.healAll?'仲間全員のHPが 合計'+total+' 回復！':actorName(target)+'のHPが '+total+' 回復！');sync()}else{let boost=charged?1.5:1,foes=s.target==='all'?livingEnemies():[state.enemy],hits=Math.max(1,s.hits||1),sum=0,lines=[];await skillMotion(s);foes.forEach((foe,i)=>{let base=s.ignoreDef?Math.max(1,member.atk+2+rand(-2,2)):damage(member.atk+2,foe.def),total=0;for(let h=0;h<hits;h++){let d=Math.max(2,Math.round(base*(s.power/hits)*boost));foe.hp=Math.max(0,foe.hp-d);total+=d}sum+=total;lines.push(foe.name+'に '+total+' ダメージ！');floatText(String(total),enemyAnchorX(foe),foe===state.enemy?85:96,state.actor==='hero'?'#ffcf55':'#b9f6ff')});sfx('hit');vibrate(28);flashEnemy();setMsg(foes.length>1?'魔物'+foes.length+'体に 合計'+sum+' ダメージ！':lines[0]);draw()}await delay(600);await finishActorTurn('skill')}
async function act(kind){if(state.mode!=='battle'||state.busy||performance.now()<(state.battleReadyAt||0))return;let member=currentActor(),e=state.enemy;if(!member||member.hp<=0)return;if(kind==='skills'){openSkillMenu();return}if(kind==='potion'){openItemMenu();return}state.busy=true;if(kind==='guard'){member.guarding=true;setMsg(actorName(member)+'は身を固めた！ このターンは防御力2倍。');sfx('guard');sync();draw();await delay(620);await finishActorTurn('guard');return}if(kind==='wait'){member.charged=true;member.expBoost=Math.min(1.5,(member.expBoost||1)+.15);setMsg(actorName(member)+'は集中して力をためた！ 次の攻撃1.5倍。');sfx('charge');sync();draw();await delay(720);await finishActorTurn('wait');return}if(kind==='run'){if(e.boss){setMsg('ボスからは逃げられない！');sfx('fleeFail');await delay(650);await finishActorTurn('run')}else if(Math.random()<.72){setMsg('二人はうまく逃げ切った！');sfx('flee');await delay(500);state.mode='field';state.enemy=null;state.enemies=[];state.busy=false;sync();draw();saveGame()}else{setMsg('回り込まれてしまった！');sfx('fleeFail');await delay(550);await finishActorTurn('run')}return}let charged=!!member.charged;member.charged=false;member.chargeUsed=charged;let boost=charged?1.5:1;if(state.actor==='hero'){let result=resolveHeroAttack(member,e);result.damage=Math.round(result.damage*boost);setMsg(result.kind==='critical'?'ルカは剣に力を集めた……':'ルカの攻撃！');await heroAttackAnimation(result.kind);if(result.kind==='miss'){sfx('miss');setMsg(e.name+'は身をかわした！');floatText('MISS',230,84,'#9aa9d8')}else{e.hp=Math.max(0,e.hp-result.damage);if(result.kind==='critical'){vibrate([35,25,90]);flashEnemy();floatText(String(result.damage)+'!',230,88,'#fff3a0');setMsg('会心の一撃！ '+e.name+'に '+result.damage+' ダメージ！')}else{sfx('hit');vibrate(20);flashEnemy();floatText(String(result.damage),230,85,'#fff176');setMsg(e.name+'に '+result.damage+' ダメージ！')}}draw();await delay(result.kind==='critical'?820:560)}else{let d=Math.max(1,Math.round(damage(Math.round(member.atk*.5)+1,e.def)*boost));setMsg('ミナは杖を構えた！');await mageStaffAnimation();e.hp=Math.max(0,e.hp-d);flashEnemy();vibrate(16);floatText(String(d),230,86,'#fff2b3');setMsg('ミナの杖！ '+e.name+'に '+d+' ダメージ！');draw();await delay(420)}await finishActorTurn('attack')}
function heroAttackAnimation(kind='normal'){return new Promise(done=>{let started=performance.now(),duration=kind==='critical'?920:BATTLE_EFFECTS.normal.duration,slashSound=false,impactSound=false;function frame(now){let p=Math.min(1,(now-started)/duration);state.heroStretch=1;state.heroLift=0;state.enemyShift=0;state.battleFlash=0;if(kind==='critical'){if(p<.16){let q=p/.16;state.battlePose=1;state.heroLunge=-11*q;state.heroLift=4*q;state.heroStretch=1-.1*q;state.criticalFx={phase:'charge',p:q}}else if(p<.28){let q=(p-.16)/.12;state.battlePose=2;state.heroLunge=-11;state.heroLift=4-15*q;state.heroStretch=.9+q*.2;state.criticalFx={phase:'charge',p:1}}else if(p<.48){let q=(p-.28)/.2;state.battlePose=3;state.heroLunge=-11+108*Math.pow(q,.55);state.heroLift=-11-24*Math.sin(q*Math.PI);state.heroStretch=1.16;state.heroAfterimage=1;state.attackFx=q;if(!slashSound){slashSound=true;sfx('slash')}}else if(p<.65){let q=(p-.48)/.17;state.battlePose=4;state.heroLunge=97;state.heroLift=-8;state.heroStretch=.94;state.heroAfterimage=1-q;state.attackFx=1;state.battleFlash=1-q;state.criticalFx={phase:'impact',p:q};if(!impactSound){impactSound=true;sfx('critical');wrap.classList.remove('shake');void wrap.offsetWidth;wrap.classList.add('shake')}}else{let q=(p-.65)/.35;state.battlePose=q<.78?5:0;state.heroLunge=97*(1-q);state.heroLift=-8*(1-q);state.heroAfterimage=0;state.attackFx=1-q;state.criticalFx={phase:'fade',p:q}}}else{if(p<.14){let q=p/.14;state.battlePose=1;state.heroLunge=-10*q;state.heroLift=3*q;state.heroStretch=1-.1*q}else if(p<.25){let q=(p-.14)/.11;state.battlePose=2;state.heroLunge=-10;state.heroLift=3-12*q;state.heroStretch=.9+q*.16}else if(p<.48){let q=(p-.25)/.23;state.battlePose=3;state.heroLunge=-10+86*Math.pow(q,.5);state.heroLift=-9-18*Math.sin(q*Math.PI);state.heroStretch=1.14;state.heroAfterimage=1;state.attackFx=q;if(!slashSound){slashSound=true;sfx('slash')}}else if(p<.63){let q=(p-.48)/.15;state.battlePose=4;state.heroLunge=76;state.heroLift=-5;state.heroStretch=.95;state.heroAfterimage=1-q;state.attackFx=1;state.battleFlash=(1-q)*.55;if(kind==='miss')state.enemyShift=18*Math.sin(q*Math.PI)}else{let q=(p-.63)/.37;state.battlePose=q<.78?5:0;state.heroLunge=76*(1-q);state.heroLift=-5*(1-q);state.heroAfterimage=0;state.attackFx=1-q}}draw();if(p<1)requestAnimationFrame(frame);else{resetBattleMotion();state.battleFlash=0;draw();done()}}requestAnimationFrame(frame)})}
// 三日月返し/牙断ち乱れ: 踏み込み→斬り抜け→反転して斬り上げ、を段数ぶん繋ぐ連続斬り
function comboSlashAnimation(label,hits=2){return new Promise(done=>{let started=performance.now(),duration=760+hits*430,head=.1,tail=.16,span=(1-head-tail)/hits,fired={};function once(k,fn){if(!fired[k]){fired[k]=1;fn()}}function frame(now){let p=Math.min(1,(now-started)/duration);state.heroStretch=1;state.heroLift=0;state.enemyShift=0;state.battleFlash=0;state.battleDim=.1*Math.sin(Math.PI*Math.min(1,p*1.25));
if(p<head){let q=p/head;state.battlePose=1;state.heroLunge=-13*q;state.heroLift=4*q;state.heroStretch=1-.09*q;state.skillFx={type:'slashCombo',phase:'ready',p,hit:-1,local:q,hits,label}}
else if(p<1-tail){let raw=(p-head)/span,i=Math.min(hits-1,Math.floor(raw)),q=raw-i,near=84+i*7,from=i===0?-13:near-30,up=i%2?-26:6;
 if(q<.4){let e=Math.pow(q/.4,.5);state.battlePose=3;state.heroLunge=from+(near-from)*e;state.heroLift=up*e-14*Math.sin(e*Math.PI);state.heroStretch=1.15;state.heroAfterimage=1;state.attackFx=q/.4;once('s'+i,()=>sfx('slash'));state.skillFx={type:'slashCombo',phase:'dash',p,hit:i,local:q/.4,hits,label}}
 else if(q<.62){let e=(q-.4)/.22;state.battlePose=4;state.heroLunge=near;state.heroLift=up;state.heroStretch=.95;state.heroAfterimage=1-e;state.attackFx=1;state.battleFlash=(1-e)*.5;state.enemyShift=9*Math.sin(e*Math.PI);once('h'+i,()=>{sfx('hit');cameraShake(2.4,90);vibrate(16)});state.skillFx={type:'slashCombo',phase:'impact',p,hit:i,local:1,hits,label}}
 else{let e=(q-.62)/.38;state.battlePose=5;state.heroLunge=near-30*e;state.heroLift=up*(1-e);state.heroAfterimage=0;state.attackFx=1-e;state.skillFx={type:'slashCombo',phase:'recoil',p,hit:i,local:1,hits,label}}}
else{let q=(p-(1-tail))/tail;state.battlePose=q<.7?5:0;state.heroLunge=(84+(hits-1)*7-30)*(1-q);state.heroLift=0;state.attackFx=0;state.skillFx={type:'slashCombo',phase:'return',p,hit:hits-1,local:1,hits,label}}
draw();if(p<1)requestAnimationFrame(frame);else{state.skillFx=null;resetBattleMotion();draw();done()}}requestAnimationFrame(frame)})}
// 断空円舞: 跳び上がって回転しながら敵全体を薙ぐ
function whirlAnimation(label){return new Promise(done=>{let started=performance.now(),duration=1720,fired={};sfx('starCharge');function once(k,fn){if(!fired[k]){fired[k]=1;fn()}}function frame(now){let p=Math.min(1,(now-started)/duration),phase='ready';state.heroStretch=1;state.enemyShift=0;state.battleFlash=0;state.battleDim=.2*Math.sin(Math.PI*Math.min(1,p*1.2));
if(p<.15){let q=p/.15;state.battlePose=2;state.heroLunge=-14*q;state.heroLift=6*q;state.heroStretch=1-.1*q}
else if(p<.28){let q=(p-.15)/.13;state.battlePose=3;state.heroLunge=-14+132*Math.pow(q,.6);state.heroLift=6-52*q;state.heroStretch=1.12;state.heroAfterimage=1;phase='leap';once('leap',()=>sfx('dash'))}
else if(p<.66){let q=(p-.28)/.38;state.battlePose=[3,4,5][Math.floor(q*9)%3];state.heroLunge=118+8*Math.sin(q*Math.PI*6);state.heroLift=-46+30*q;state.heroStretch=1+.1*Math.sin(q*Math.PI*6);state.heroAfterimage=1;phase='spin';[0,.34,.68].forEach((k,i)=>{if(q>k)once('sp'+i,()=>{sfx('slash');cameraShake(2,70)})})}
else if(p<.76){let q=(p-.66)/.1;state.battlePose=4;state.heroLunge=118;state.heroLift=-16+16*q;state.heroAfterimage=1-q;state.battleFlash=1-q;phase='burst';once('burst',()=>{sfx('starBurst');cameraShake(5.5,170);vibrate(48)})}
else{let q=(p-.76)/.24;state.battlePose=q<.72?5:0;state.heroLunge=118*(1-q);state.heroLift=0;state.heroAfterimage=0;phase='return'}
state.skillFx={type:'whirl',phase,p,label};draw();if(p<1)requestAnimationFrame(frame);else{state.skillFx=null;resetBattleMotion();draw();done()}}requestAnimationFrame(frame)})}
// 鎧断ち: 大きく振りかぶって装甲ごと断ち割る一撃
function pierceAnimation(label){return new Promise(done=>{let started=performance.now(),duration=1560,fired={};sfx('starCharge');function once(k,fn){if(!fired[k]){fired[k]=1;fn()}}function frame(now){let p=Math.min(1,(now-started)/duration),phase='charge';state.heroStretch=1;state.enemyShift=0;state.battleFlash=0;state.battleDim=p<.72?.22:.22*Math.max(0,(.92-p)/.2);
if(p<.3){let q=p/.3;state.battlePose=2;state.heroLunge=-13*q;state.heroLift=-15*q;state.heroStretch=1+.08*q}
else if(p<.38){state.battlePose=2;state.heroLunge=-13;state.heroLift=-15;phase='silence';once('quiet',()=>sfx('silence'))}
else if(p<.52){let q=(p-.38)/.14;state.battlePose=3;state.heroLunge=-13+113*Math.pow(q,.45);state.heroLift=-15+13*q;state.heroStretch=1.18;state.heroAfterimage=1;state.attackFx=q;phase='thrust';once('slash',()=>sfx('slash'))}
else if(p<.66){let q=(p-.52)/.14;state.battlePose=4;state.heroLunge=100;state.heroLift=-2;state.heroAfterimage=1-q;state.attackFx=1;state.battleFlash=1-q;state.enemyShift=15*Math.sin(q*Math.PI);phase='break';once('impact',()=>{sfx('starImpact');cameraShake(5,180);vibrate(60)})}
else{let q=(p-.66)/.34;state.battlePose=q<.7?5:0;state.heroLunge=100*(1-q);state.heroLift=0;state.attackFx=1-q;phase='linger'}
state.skillFx={type:'pierce',phase,p,label};draw();if(p<1)requestAnimationFrame(frame);else{state.skillFx=null;resetBattleMotion();draw();done()}}requestAnimationFrame(frame)})}
// 星屑の雨 / 星降り: 杖を掲げ、敵全体へ星光を降らせる
function starShowerAnimation(label,big=false){return new Promise(done=>{let started=performance.now(),duration=big?2000:1660,fired={};sfx('moonCast');function once(k,fn){if(!fired[k]){fired[k]=1;fn()}}function frame(now){let p=Math.min(1,(now-started)/duration),phase='cast';state.battleDim=(big?.3:.2)*Math.sin(Math.PI*Math.min(1,p*1.15));state.mageCast=Math.sin(Math.PI*Math.min(1,p*1.1));state.mageSpin=p*1.6;state.mageFrame=p<.14?1:p<.26?2:p<.72?3:p<.9?4:0;state.mageLift=-4*Math.sin(Math.PI*Math.min(1,p*1.3));
if(p<.26){phase='cast';once('orb',()=>{if(p>.18)sfx('moonOrb')})}
else if(p<.74){phase='rain';once('shot',()=>sfx('moonShot'));[.34,.46,.58,.68].forEach((k,i)=>{if(p>k)once('r'+i,()=>{sfx('moonHit');cameraShake(big?2.6:1.8,80);state.enemyShift=6})});state.enemyShift=5*Math.sin((p-.26)/.48*Math.PI*4)}
else if(big&&p<.84){phase='burst';state.battleFlash=1-(p-.74)/.1;once('burst',()=>{sfx('moonBurst');cameraShake(6,200);vibrate(52)})}
else{phase='fade';state.enemyShift=0}
state.skillFx={type:'starshower',phase,p,big,label};draw();if(p<1)requestAnimationFrame(frame);else{state.skillFx=null;state.mageCast=0;state.mageFrame=0;state.mageSpin=0;resetBattleMotion();draw();done()}}requestAnimationFrame(frame)})}
function starfireAnimation(label='星 火 斬 り'){return new Promise(done=>{let started=performance.now(),duration=BATTLE_EFFECTS.starfire.duration,sounds={};sfx('starCharge');function once(k,fn){if(!sounds[k]){sounds[k]=1;fn()}}function frame(now){let p=Math.min(1,(now-started)/duration),phase='charge';state.heroStretch=1;state.battleDim=p<.7?BATTLE_EFFECTS.starfire.darken:BATTLE_EFFECTS.starfire.darken*Math.max(0,(.875-p)/.175);state.enemyShift=0;if(p<.175){let q=p/.175;state.battlePose=2;state.heroLunge=-12*q;state.heroLift=3*q;state.heroStretch=1+.06*q;phase='charge'}else if(p<.25){state.battlePose=2;state.heroLunge=-12;state.heroLift=3;phase='silence';once('quiet',()=>sfx('silence'))}else if(p<.325){let q=(p-.25)/.075;state.battlePose=3;state.heroLunge=-12+224*Math.pow(q,.42);state.heroLift=-4;state.heroAfterimage=1;phase='dash';once('dash',()=>sfx('starDash'))}else if(p<.45){state.battlePose=5;state.heroLunge=212;state.heroLift=-2;state.heroAfterimage=Math.max(0,1-(p-.325)/.05);phase='pass'}else if(p<.505){state.battlePose=4;state.heroLunge=212;state.heroLift=-2;phase='impact';state.battleFlash=1-Math.abs(p-.475)/.03;once('impact',()=>{sfx('starImpact');cameraShake(BATTLE_EFFECTS.starfire.shake,155);vibrate(55)})}else if(p<.6){let q=(p-.505)/.095;state.battlePose=5;state.heroLunge=212;state.enemyShift=16*Math.sin(Math.min(1,q)*Math.PI/2);phase='pillar';once('burst',()=>sfx('starBurst'))}else if(p<.875){state.battlePose=5;state.heroLunge=212;state.enemyShift=16*(1-(p-.6)/.275);phase='linger'}else{let q=(p-.875)/.125;state.battlePose=q<.75?3:0;state.heroLunge=212*(1-q);phase='return'}state.skillFx={type:'fire',phase,p,label};draw();if(p<1)requestAnimationFrame(frame);else{state.skillFx=null;resetBattleMotion();draw();done()}}requestAnimationFrame(frame)})}
function healingAnimation(label='光 の 癒 し'){return new Promise(done=>{let started=performance.now(),duration=BATTLE_EFFECTS.heal.duration;sfx('heal');function frame(now){let p=Math.min(1,(now-started)/duration);state.skillFx={type:'heal',phase:p<.28?'circle':p<.68?'pillar':'fade',p,label};state.battleDim=BATTLE_EFFECTS.heal.darken*Math.sin(Math.PI*p);state.battlePose=p<.72?2:0;state.heroLift=-5*Math.sin(Math.PI*p);state.heroStretch=1+.035*Math.sin(Math.PI*p);draw();if(p<1)requestAnimationFrame(frame);else{state.skillFx=null;resetBattleMotion();draw();done()}}requestAnimationFrame(frame)})}
function mageStaffAnimation(){return new Promise(done=>{let started=performance.now(),swung=false,hit=false,duration=690,distance=78;function ease(t){return 1-Math.pow(1-Math.max(0,Math.min(1,t)),3)}function frame(now){let p=Math.min(1,(now-started)/duration);state.mageCast=0;state.skillFx=null;if(p<.14){state.mageFrame=0;state.mageLunge=-3*ease(p/.14);state.mageStaffStrike=0}else if(p<.43){state.mageFrame=1;state.mageLunge=-3+(distance+3)*ease((p-.14)/.29);state.mageLift=-3*Math.sin(Math.PI*(p-.14)/.29);state.mageStaffStrike=-.4}else if(p<.61){let q=(p-.43)/.18;state.mageFrame=q<.5?3:4;state.mageLunge=distance;state.mageStaffStrike=-.7+1.7*ease(q);if(!swung){swung=true;sfx('staffSwing')}if(!hit&&p>=.52){hit=true;sfx('staffImpact');state.enemyShift=7;state.staffFx={p:0}}if(state.staffFx)state.staffFx.p=Math.min(1,Math.max(0,(p-.52)/.2))}else if(p<.74){state.mageFrame=5;state.mageLunge=distance;state.mageStaffStrike=.8*(1-(p-.61)/.13);state.enemyShift=Math.max(0,7*(1-(p-.61)/.13))}else{let q=ease((p-.74)/.26);state.mageFrame=0;state.mageLunge=distance*(1-q);state.mageStaffStrike=0;state.enemyShift=0;state.staffFx=null}draw();if(p<1)requestAnimationFrame(frame);else{resetBattleMotion();draw();done()}}requestAnimationFrame(frame)})}
function moonMagicAnimation(kind='attack',label){return new Promise(done=>{let started=performance.now(),healKind=kind==='heal'||kind==='veil',cfg=healKind?BATTLE_EFFECTS.heal:BATTLE_EFFECTS.moon,duration=cfg.duration*(kind==='veil'?1.15:1),sounds={};sfx(healKind?'heal':'moonCast');function once(k,fn){if(!sounds[k]){sounds[k]=1;fn()}}function frame(now){let p=Math.min(1,(now-started)/duration),phase;if(healKind)phase=p<.3?'circle':p<.7?'pillar':'fade';else if(p<.25)phase='cast';else if(p<.41)phase='orb';else if(p<.54)phase='projectile';else if(p<.59)phase='impact';else if(p<.72)phase='crescent';else phase='fade';state.battleDim=cfg.darken*Math.sin(Math.PI*Math.min(1,p*1.2));state.mageCast=Math.sin(Math.PI*Math.min(1,p*1.15));state.mageFrame=p<.18?1:p<.36?2:p<.58?3:p<.78?4:p<.94?5:0;state.mageSpin=p*1.8;state.skillFx={type:kind==='heal'?'moonheal':kind==='veil'?'veil':'moon',phase,p,label};if(!healKind){if(p>.25)once('orb',()=>sfx('moonOrb'));if(p>.41)once('shot',()=>sfx('moonShot'));if(p>.54)once('hit',()=>{sfx('moonHit');cameraShake(cfg.shake,115);vibrate(24)});if(p>.62)once('burst',()=>sfx('moonBurst'));state.enemyShift=p>.54&&p<.72?5*Math.sin((p-.54)/.18*Math.PI):0}draw();if(p<1)requestAnimationFrame(frame);else{state.mageCast=0;state.mageFrame=0;state.mageSpin=0;state.skillFx=null;resetBattleMotion();draw();done()}}requestAnimationFrame(frame)})}
function livingMembers(){return[state.hero,...(state.companion.active?[state.companion]:[])].filter(v=>v.hp>0)}
function pickEnemyTarget(){let living=livingMembers();return living.length===1?living[0]:(Math.random()<.58?state.hero:state.companion)}
async function enemyHit(target,multiplier,label){if(!target||target.hp<=0)return 0;let isHero=target===state.hero,name=isHero?'ルカ':'ミナ',d=Math.max(1,Math.round(damage(state.enemy.atk,effectiveDefense(target))*multiplier));sfx('enemy');target.hp=Math.max(0,target.hp-d);if(target.hp>0&&target.hp<=target.maxHp*.25)sfx('lowHp');if(isHero)state.heroHit=1;else state.mageHit=1;wrap.classList.remove('shake');void wrap.offsetWidth;wrap.classList.add('shake');setTimeout(()=>{sfx('hit');vibrate([45,25,55]);if(isHero)state.heroHit=0;else state.mageHit=0;if(state.mode==='battle')draw()},150);floatText(String(d),isHero?53:112,185,target.guarding?'#7be8ff':'#ff746c');setMsg(label+'！ '+name+'は '+d+' ダメージ！'+(target.guarding?'（防御）':''));sync();await delay(560);if(target.hp<=0){setMsg(name+'は戦闘不能になった！');await delay(430)}return d}
async function enemyTurn(){if(!livingMembers().length){gameOver();return}for(let e of [...livingEnemies()]){state.enemy=e;e.turn=(e.turn||0)+1;let action=selectEnemyAction(e);if(action.type==='charge'){e.charging=true;setMsg(e.name+'は力をためている……');sfx('enemy');await enemyAttackAnimation('charge')}else if(action.type==='all'){setMsg(e.name+'の '+action.label+'！');sfx('burst');await enemyAttackAnimation('all');for(let target of [...livingMembers()])await enemyHit(target,action.multiplier,action.label)}else{if(action.clearsCharge)e.charging=false;let absorbed=0,hits=action.hits||1;for(let i=0;i<hits;i++){let target=pickEnemyTarget();if(!target)break;await enemyAttackAnimation(action.drain?'drain':'attack');absorbed+=await enemyHit(target,action.multiplier,e.name+'の '+action.label);if(!livingMembers().length)break}if(action.drain&&absorbed>0){let heal=Math.min(Math.max(1,Math.round(absorbed*action.drain)),e.maxHp-e.hp);if(heal>0){e.hp+=heal;floatText('+'+heal,230,92,'#8dff9b');setMsg(e.name+'は生命力を '+heal+' 奪った！');draw();await delay(360)}}}if(!livingMembers().length){gameOver();return}}chooseEnemyTarget()}
async function applyLevelUps(){let h=state.hero,m=state.companion;while(h.exp>=h.next){h.exp-=h.next;h.lv++;h.next=Math.floor(h.next*1.55);h.maxHp+=8;h.atk+=3;h.def+=2;h.hp=h.maxHp;sync();sfx('level');speak('レベルアップ！');setMsg('ルカが LV '+h.lv+'になった！ 能力上昇・HP全回復！');await delay(950)}if(m.active)while(m.exp>=m.next){m.exp-=m.next;m.lv++;m.next=Math.floor(m.next*1.55);m.maxHp+=6;m.atk+=3;m.def+=1;m.hp=m.maxHp;sync();sfx('level');setMsg('ミナが LV '+m.lv+'になった！ 魔力上昇・HP全回復！');await delay(1000)}}
function grantDrops(enemy){let found=rollDrops(enemy);found.forEach(drop=>addItem(drop.id,drop.amount));return found.map(drop=>ITEMS[drop.id].name+' ×'+drop.amount)}
async function win(){let foes=state.enemies?.length?state.enemies:[state.enemy],boss=foes.find(e=>e.boss),baseExp=foes.reduce((sum,e)=>sum+e.exp,0),h=state.hero,m=state.companion,heroExp=Math.round(baseExp*(h.expBoost||1)),mageExp=Math.round(baseExp*(m.expBoost||1));setMsg((foes.length>1?'魔物たち':foes[0].name)+'を倒した！ EXP '+heroExp+'を獲得！');sfx('win');h.exp+=heroExp;if(m.active)m.exp+=mageExp;await defeatEffect(!!boss);await applyLevelUps();let drops=foes.flatMap(grantDrops);if(drops.length){setMsg('戦利品：'+drops.join('、')+'を手に入れた！');sfx('itemGet');sync();await delay(850)}for(let member of[h,m]){member.guarding=false;member.charged=false;member.expBoost=1}if(boss){speak('やった！');state.bossAlive=false;state.cleared=true;state.mode='clear';state.enemy=null;state.enemies=[];state.busy=false;state.itemMenu=false;saveGame();sync();draw();showOverlay('clear');return}state.mode='field';state.enemy=null;state.enemies=[];state.busy=false;state.skillMenu=false;state.itemMenu=false;sync();draw();saveGame()}
